/* 道具：心臓マッサージのテンポ */
let tempoTimer=null, tempoN=0, tempoCtx=null;
function krTempo(){
  const b=$('krTpBtn'); if(!b) return;
  if(tempoTimer){ clearInterval(tempoTimer); tempoTimer=null; b.textContent='▶ はじめる'; b.classList.remove('on'); return; }
  try{ tempoCtx=tempoCtx||new (window.AudioContext||window.webkitAudioContext)(); tempoCtx.resume&&tempoCtx.resume(); }catch(_){ tempoCtx=null; }
  const bpm=+($('krTpBpm')?.value||110); tempoN=0; b.textContent='■ とめる'; b.classList.add('on');
  const tick=()=>{ tempoN++; const c=$('krTpN'); if(!c){ clearInterval(tempoTimer); tempoTimer=null; return; }
    const k=((tempoN-1)%30)+1; c.textContent=k; c.classList.toggle('last', k===30);
    const d=$('krTpDot'); if(d){ d.classList.remove('beat'); void d.offsetWidth; d.classList.add('beat'); }
    if(tempoCtx){ try{ const o=tempoCtx.createOscillator(), g=tempoCtx.createGain(); o.frequency.value=k===30?1320:880; g.gain.value=.25; o.connect(g); g.connect(tempoCtx.destination); o.start(); o.stop(tempoCtx.currentTime+.06); }catch(_){} }
    if(navigator.vibrate) try{ navigator.vibrate(30); }catch(_){} };
  tick(); tempoTimer=setInterval(tick, 60000/bpm);
}
function krTempoRe(){ if(tempoTimer){ krTempo(); krTempo(); } }
function krTempoStop(){ if(tempoTimer){ clearInterval(tempoTimer); tempoTimer=null; const b=$('krTpBtn'); if(b){ b.textContent='▶ はじめる'; b.classList.remove('on'); } } }
