function krHikRun(){
  const o=$('krHkOut'); if(!o) return; const d=parseDate($('krHkIn').value); if(!d){ o.innerHTML=''; return; }
  const now=new Date(); now.setHours(0,0,0,0);
  o.innerHTML=`<table class="kr-t"><tr><th>日付</th><th>やること</th></tr>${HIK.map(([n,t])=>{ const x=addD(d,n,'d'); return `<tr class="${x<now?'kr-past':''}${n===0?' kr-now':''}"><td><b>${ymd(x)}</b><br><small>${n<0?-n+'日前':n===0?'当日':n+'日後'}</small></td><td>${t}</td></tr>`; }).join('')}</table>`;
}
