const VAC=[[2,'m','5種混合①・肺炎球菌①・B型肝炎①・ロタ①'],[3,'m','5種混合②・肺炎球菌②・B型肝炎②・ロタ②'],[4,'m','5種混合③・肺炎球菌③'],[5,'m','BCG（5〜8か月）'],[7,'m','B型肝炎③（7〜8か月）'],[12,'m','MR 1期・水痘①・肺炎球菌④'],[12,'m','5種混合④（1歳〜1歳半）'],[18,'m','1歳6か月児健診・水痘②（1歳半〜2歳）'],[36,'m','3歳児健診・日本脳炎①②'],[48,'m','日本脳炎（追加）']];
function krBabyRun(){
  const o=$('krBbOut'); if(!o) return; const d=parseDate($('krBbIn').value); if(!d){ o.innerHTML=''; return; }
  const now=new Date(); now.setHours(0,0,0,0);
  const todo=[[13,'d','出生届（生まれた日を含めて14日以内）'],[15,'d','児童手当の申請（翌日から15日以内）'],[30,'d','1か月健診・健康保険の加入（目安）']];
  const row=(x,t,lab)=>`<tr class="${x<now?'kr-past':''}"><td><b>${ymd(x)}</b><br><small>${lab}</small></td><td>${t}</td></tr>`;
  o.innerHTML=`<h4>手続き</h4><table class="kr-t"><tr><th>期限・目安</th><th>こと</th></tr>${todo.map(([n,u,t])=>row(addD(d,n,u),t,n+'日')).join('')}</table>
  <h4>予防接種・健診（標準的な時期の目安）</h4><table class="kr-t"><tr><th>ころ</th><th>こと</th></tr>${VAC.map(([n,u,t])=>row(addD(d,n,u),t,n>=12?(n%12?Math.floor(n/12)+'歳'+(n%12)+'か月':n/12+'歳'):n+'か月')).join('')}</table>
  ${NOTE('予防接種の日程は、かかりつけの小児科・市区町村の案内に従ってください。ここに出すのは「受け始めの目安」です。')}`;
}
