function krCarRun(){
  const o=$('krCdOut'); if(!o) return; const now=new Date(); now.setHours(0,0,0,0); let h='';
  const s=parseDate($('krCdS').value);
  if(s){ const from=addD(s,-2,'m'); const left=Math.round((s-now)/864e5);
    h+=`<h4>車検</h4><p>満了日 <b>${ymd(s)}</b>（${left>=0?'あと'+left+'日':'<b>'+(-left)+'日過ぎています</b>'}）<br>受けられるのは <b>${ymd(from)}</b> から（次の満了日は ${ymd(addD(s,2,'y'))}）</p>`; }
  const b=parseDate($('krCdB').value), ey=+$('krCdY').value;
  if(b && ey){ const bd=new Date(ey,b.getMonth(),b.getDate()); const a=addD(bd,-1,'m'), z=addD(bd,1,'m'); const age=ey-b.getFullYear();
    h+=`<h4>免許の更新</h4><p>更新できる期間 <b>${ymd(a)}</b> 〜 <b>${ymd(z)}</b><br>その年の誕生日で <b>${age}歳</b>${age>=75?'（認知機能検査・高齢者講習）':age>=70?'（高齢者講習）':''}</p>`; }
  o.innerHTML=h||'<div class="kr-empty">日付を入れてください</div>';
}
P.push({id:'tool-carday', cat:'car', t:'🧮 車検・免許更新の時期の計算', k:'車検 免許 更新 いつ 期間 計算 満了日 誕生日',
h:()=>`<div class="kr-form"><label>車検の満了日（車検証・ステッカー）<input type="date" id="krCdS" oninput="krCarRun()"></label>
<div class="kr-grid"><label>誕生日<input type="date" id="krCdB" oninput="krCarRun()" value="1960-06-15"></label><label>免許の有効期限の年（西暦）<input type="number" id="krCdY" inputmode="numeric" oninput="krCarRun()"></label></div></div><div id="krCdOut"></div>`,
init:()=>{ const y=$('krCdY'); if(y && !y.value) y.value=new Date().getFullYear()+1; const c=$('krCdS'); if(c && !c.value){ const d=new Date(); d.setDate(d.getDate()+300); c.value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); } krCarRun(); }});
