const COOL={hou:['訪問販売',8],den:['電話勧誘販売',8],esu:['エステ・塾・語学教室など（特定継続的役務）',8],kai:['訪問購入',8],mar:['マルチ商法（連鎖販売取引）',20],nai:['内職・モニター商法',20]};
function krCoolRun(){
  const o=$('krClOut'); if(!o) return; const d=parseDate($('krClD').value); const c=COOL[$('krClT').value]; if(!d){ o.innerHTML=''; return; }
  const last=addD(d,c[1]-1,'d'); const now=new Date(); now.setHours(0,0,0,0); const left=Math.round((last-now)/864e5);
  const co=$('krClCo').value||'〇〇株式会社', it=$('krClIt').value||'〇〇', am=$('krClAm').value||'〇〇';
  o.innerHTML=`<p class="kr-big">期限 <b>${ymd(last)}</b> まで（${c[1]}日間）<br><small>${left>=0?'<b>あと'+(left+1)+'日</b>（今日を含む）':'<b>期間は過ぎています</b>（書面の不備などでできる場合もあるので188へ相談）'}</small></p>`
   +EX('通知の文例（はがき）',`契約解除通知書\n\n次の契約を解除します。\n\n契約年月日　${ymd(d).replace(/（.）/,'')}\n商品名　${it}\n契約金額　${am}円\n販売会社　${co}\n担当者　〇〇\n\n支払った代金〇〇円を返金し、商品を引き取ってください。\n\n令和〇年〇月〇日\n住所\n氏名`)
   +`${OK('はがきの<b>両面をコピー</b>し、郵便局で<b>特定記録郵便か簡易書留</b>で送る（期間内に出せばよい）')}${OK('クレジット払いの時は、<b>カード会社（信販会社）にも</b>同じ通知を送る')}${OK('メールやお店のフォームでもできる（2022年6月から）。送った画面を保存する')}`;
}
P.push({id:'tool-cooling', cat:'hou', t:'🧮 クーリング・オフの期限と通知の文例', k:'クーリング・オフ 期限 計算 いつまで 何日 通知 はがき 書き方 文例',
h:()=>`<div class="kr-form"><label>取引の種類<select id="krClT" onchange="krCoolRun()">${Object.entries(COOL).map(([k,v])=>`<option value="${k}">${v[0]}（${v[1]}日）</option>`).join('')}</select></label>
<label>契約書面を受け取った日<input type="date" id="krClD" oninput="krCoolRun()"></label>
<div class="kr-grid"><label>販売会社<input id="krClCo" oninput="krCoolRun()" placeholder="〇〇株式会社"></label><label>商品・サービス<input id="krClIt" oninput="krCoolRun()" placeholder="羽毛布団"></label><label>契約金額（円）<input id="krClAm" inputmode="numeric" oninput="krCoolRun()" placeholder="300,000"></label></div></div><div id="krClOut"></div>`,
init:()=>{ const i=$('krClD'); if(i && !i.value) i.value=todayStr(); krCoolRun(); }});

