  const base=Math.min(100000, s<2000000?s*0.05:100000); const d=Math.min(2000000,Math.max(0,a-h-base));
  const rate=s<=1950000?.05:s<=3300000?.10:s<=6950000?.20:s<=9000000?.23:s<=18000000?.33:s<=40000000?.40:.45;
